mapper.sql:
owi.is_deleted = FALSE
AND owid.is_deleted = FALSE


    AND owi.code ILIKE concat('%',#{params.code}::text,'%')



    AND owi.source_code ILIKE concat('%',#{params.sourceCode}::text,'%')



    AND owi.instock_type = #{params.instockType}



    AND owi.delivery_mode = #{params.deliveryMode}



    AND owi.instock_status in

        #{item}




    AND owi.logistics_method in

        #{item}





    AND owi.delivery_warehouse_id in

        #{item}




    AND owi.transfer_warehouse_id in

        #{item}




    AND owi.to_warehouse_id in

        #{item}




    and owid.is_combination = #{params.isCombination}



    AND owid.sku_no ILIKE concat('%',#{params.skuNo}::text,'%')



    AND owid.platform_sku_no ILIKE concat('%',#{params.platformSkuNo}::text,'%')



    AND owid.sku_no in

        #{item}





    AND owid.platform_sku_no in

        #{item}





    AND owi.create_user_id IN

        #{createUserId}




    AND owi.create_time >= #{params.createTimeList[0]}
    AND (#{params.createTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > owi.create_time



    AND owi.receive_time >= #{params.receiveTimeList[0]}
    AND (#{params.receiveTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > owi.receive_time



    AND owid.diff_qty ${params.diffRule} 0




    ${params.permissionSql}

ORDER BY


        ${item.field} ${item.sort}


owi.create_time DESC

mapper.select:
SELECT owi.id, owi.code, owid.id AS detailId, owi.create_time, owi.create_user_name, owi.create_user_id, owi.dict_platform, owi.source_code, owi.source_id, owi.source_type, owi.instock_type, owi.instock_status, owi.delivery_warehouse_name, owi.delivery_warehouse_id, owi.transfer_warehouse_name, owi.transfer_warehouse_id, owi.to_warehouse_name, owi.to_warehouse_id, owi.logistics_method, owi.remark, owi.receive_time, owi.estimated_arrival_date, owi.finish_reason, owi.finish_status, owi.overseas_warehouse_inbound_id, owi.delivery_mode, owid.platform_product_name, owid.platform_sku_no, owid.product_name, owid.sku_no, owid.sku_id, owid.is_combination, owid.receive_qty, owid.transport_qty, owid.pack_qty, owid.diff_qty, owid.receive_time AS detailReceiveTime, owid.receive_status, owid.receive_type FROM overseas_warehouse_inbound owi INNER JOIN overseas_warehouse_inbound_detail owid ON owi.id = owid.main_id
and owi.id in
#{item}
